/**
 * Explicit APK compatibility window for the public mobile contract.
 * Versions use the sortable YYYY.MM.DD.PP format generated by the Android release.
 */
export const APK_COMPATIBILITY = Object.freeze({
  pairedVersion: '2026.08.11.02',
  minSupportedVersion: '2026.07.30.01',
  maxTestedVersion: '2026.08.11.02',
  pairedSourceFingerprint: '8909c4445aaf5f53',
  protocolVersion: '2026.07.10.10',
  policyVersion: 'valorae-apk-compatibility-v2-backward-compatible',
});

function truthy(value) {
  return ['1', 'true', 'yes', 'sim', 'on'].includes(String(value || '').trim().toLowerCase());
}

function productionRuntime() {
  return process.env.VERCEL === '1' || String(process.env.NODE_ENV || '').toLowerCase() === 'production';
}

export function normalizeApkVersion(value = '') {
  const clean = String(value || '').trim();
  return /^\d{4}\.\d{2}\.\d{2}\.\d{2}$/.test(clean) ? clean : '';
}

export function compareApkVersions(left = '', right = '') {
  const a = normalizeApkVersion(left);
  const b = normalizeApkVersion(right);
  if (!a || !b) return Number.NaN;
  const aa = a.split('.').map(Number);
  const bb = b.split('.').map(Number);
  for (let index = 0; index < Math.max(aa.length, bb.length); index += 1) {
    const delta = (aa[index] || 0) - (bb[index] || 0);
    if (delta) return delta < 0 ? -1 : 1;
  }
  return 0;
}

export function apkVersionFromRequest(req = {}) {
  const headers = req?.headers || {};
  return normalizeApkVersion(headers['x-valorae-app-version'] ?? headers['X-Valorae-App-Version'] ?? '');
}

export function apkSourceFingerprintFromRequest(req = {}) {
  const headers = req?.headers || {};
  const clean = String(headers['x-valorae-source-fingerprint'] ?? headers['X-Valorae-Source-Fingerprint'] ?? '').trim().toLowerCase();
  return /^[0-9a-f]{16}$/.test(clean) ? clean : '';
}

export function annotateSourceFingerprint(evaluation = {}, sourceFingerprint = '') {
  const normalized = /^[0-9a-f]{16}$/.test(String(sourceFingerprint || '').trim().toLowerCase())
    ? String(sourceFingerprint).trim().toLowerCase()
    : '';
  return {
    ...evaluation,
    sourceFingerprint: normalized,
    pairedSourceFingerprint: APK_COMPATIBILITY.pairedSourceFingerprint,
    sourceFingerprintStatus: !normalized
      ? 'MISSING'
      : normalized === APK_COMPATIBILITY.pairedSourceFingerprint ? 'PAIRED' : 'DIVERGENT',
  };
}

export function evaluateApkCompatibility(version = '', options = {}) {
  const normalized = normalizeApkVersion(version);
  const rejectFutureConfigured = process.env.VALORAE_REJECT_UNTESTED_FUTURE_APK;
  const allowFuture = options.allowFuture ?? (
    rejectFutureConfigured === undefined || rejectFutureConfigured === ''
      ? !productionRuntime()
      : !truthy(rejectFutureConfigured)
  );
  if (!normalized) {
    return {
      ok: false,
      reject: true,
      status: 'INVALID',
      reason: 'invalid_or_missing_version',
      version: '',
      allowFuture,
      ...APK_COMPATIBILITY,
    };
  }
  if (compareApkVersions(normalized, APK_COMPATIBILITY.minSupportedVersion) < 0) {
    return {
      ok: false,
      reject: true,
      status: 'UPDATE_REQUIRED',
      reason: 'below_minimum_supported',
      version: normalized,
      allowFuture,
      ...APK_COMPATIBILITY,
    };
  }
  if (compareApkVersions(normalized, APK_COMPATIBILITY.maxTestedVersion) > 0) {
    return {
      ok: allowFuture,
      reject: !allowFuture,
      status: allowFuture ? 'FUTURE_UNTESTED_ALLOWED' : 'FUTURE_UNTESTED_REJECTED',
      reason: 'above_maximum_tested',
      version: normalized,
      allowFuture,
      ...APK_COMPATIBILITY,
    };
  }
  return {
    ok: true,
    reject: false,
    status: normalized === APK_COMPATIBILITY.pairedVersion ? 'PAIRED' : 'SUPPORTED',
    reason: undefined,
    version: normalized,
    allowFuture,
    ...APK_COMPATIBILITY,
  };
}

export function applyApkCompatibilityHeaders(res, evaluation = null) {
  const state = evaluation || {};
  res.setHeader('X-Valorae-Paired-Apk-Version', APK_COMPATIBILITY.pairedVersion);
  res.setHeader('X-Valorae-Min-Apk-Version', APK_COMPATIBILITY.minSupportedVersion);
  res.setHeader('X-Valorae-Max-Tested-Apk-Version', APK_COMPATIBILITY.maxTestedVersion);
  res.setHeader('X-Valorae-Paired-Source-Fingerprint', APK_COMPATIBILITY.pairedSourceFingerprint);
  res.setHeader('X-Valorae-Source-Fingerprint-Status', String(state.sourceFingerprintStatus || 'UNKNOWN'));
  res.setHeader('X-Valorae-Apk-Compatibility', String(state.status || 'UNKNOWN'));
}
